define(["jquery","mod_videoprogress/html5"],function($,Html5Adapter){const loadScript=url=>new Promise((resolve,reject)=>{if(window.Hls){resolve(window.Hls);return}const script=document.createElement("script");script.src=url;script.onload=()=>resolve(window.Hls);script.onerror=reject;document.head.appendChild(script)});class HlsAdapter extends Html5Adapter{initialise(){if(this.video&&this.video.canPlayType("application/vnd.apple.mpegurl")){this.video.src=this.config.url;return super.initialise()}return loadScript(this.config.hlsjsurl).then(Hls=>{if(!Hls||!Hls.isSupported()){throw new Error("HLS is not supported by this browser")}this.hls=new Hls({enableWorker:true,lowLatencyMode:true});this.hls.loadSource(this.config.url);this.hls.attachMedia(this.video);return super.initialise()})}}return HlsAdapter});